let current=null,selected=null,dirty=false,toastTimer;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function goto(page){$$('.page').forEach(e=>e.classList.toggle('hidden',e.id!==page));$$('nav button').forEach(e=>e.classList.toggle('active',e.dataset.page===page));$('#crumb').textContent={home:'내 책상',diaries:'내 다이어리',templates:'템플릿 둘러보기',stickers:'스티커 서랍'}[page];window.scrollTo(0,0)}
$$('[data-page]').forEach(b=>b.onclick=()=>goto(b.dataset.page));$$('[data-goto]').forEach(b=>b.onclick=()=>goto(b.dataset.goto));$('.logo').onclick=e=>{e.preventDefault();goto('home')};
function renderDiaries(){['#home-diaries','#all-diaries'].forEach(target=>{const root=$(target);root.replaceChildren();(target==='#home-diaries'?diaries.slice(0,3):diaries).forEach(d=>{const card=el('button','diary-card');const cover=el('div','cover');const img=el('img');img.src=d.items?.find(i=>i.type==='photo')?.content||photos[d.image]||photos.lake;img.alt=d.title;cover.append(img,el('span','cover-label',d.title),el('span','cover-spark','✧'));card.append(cover,el('h3','',d.title));const meta=el('p','',d.date+' · '+(d.subtitle||'나의 기록'));meta.append(el('span','','비공개'));card.append(meta);card.onclick=()=>openEditor(d);root.append(card)});const add=el('button','blank');add.append(el('b','','＋'),el('span','','새로운 이야기 시작하기'),el('small','','나만의 페이지를 채워보세요'));add.onclick=()=>openEditor();root.append(add)});$('#count').textContent=diaries.length;$('#diary-total').textContent=diaries.length}
function renderTemplates(root,list){$(root).replaceChildren();list.forEach(t=>{const card=el('button','template-card');const preview=el('div','template-preview');preview.style.background=t[3];const paper=el('div','mini-page');paper.append(el('h4','',t[0]));const img=el('img');img.src=photos[t[2]];img.alt=t[0]+' 템플릿';img.loading='lazy';paper.append(img,el('span','decoration',t[4]),el('p','','오늘의 순간을 오래 기억하고 싶어.\n작고 소중한 나의 하루 ♡'));preview.append(paper);const title=el('h3','',t[0]);title.append(el('span','','무료'));card.append(preview,title,el('p','',t[1]+' · 사진과 글로 채우는 한 페이지'));card.onclick=()=>openEditor(null,templates.indexOf(t));$(root).append(card)})}
$$('#home-chips button').forEach(b=>b.onclick=()=>{$$('#home-chips button').forEach(c=>c.classList.toggle('selected',c===b));renderTemplates('#home-templates',(b.textContent==='전체'?templates:templates.filter(t=>t[1]===b.textContent)).slice(0,4))});
let category='전체';function renderStickers(){const query=$('#sticker-search').value.trim();$('#sticker-grid').replaceChildren();const list=stickers.filter(s=>(category==='전체'||category===s.category)&&(!query||s.category.includes(query)||s.emoji.includes(query)));list.forEach(s=>{const b=el('button','',s.emoji);b.append(el('small','',s.category));b.setAttribute('aria-label',s.emoji+' 스티커 추가');b.onclick=()=>{openEditor();addPiece({type:'sticker',content:s.emoji,x:340,y:360});};$('#sticker-grid').append(b)});if(!list.length)$('#sticker-grid').append(el('p','','찾는 스티커가 없어요. 다른 단어로 검색해보세요.'))}
['전체',...Object.keys(groups)].forEach(c=>{const b=el('button',c==='전체'?'selected':'',c);b.onclick=()=>{category=c;$$('#sticker-categories button').forEach(x=>x.classList.toggle('selected',x===b));renderStickers()};$('#sticker-categories').append(b)});$('#sticker-search').oninput=renderStickers;
stickers.forEach(s=>{const b=el('button','',s.emoji);b.title=s.category;b.onclick=()=>addPiece({type:'sticker',content:s.emoji,x:80+Math.random()*350,y:160+Math.random()*360});$('#editor-stickers').append(b)});
function defaultItems(index){const t=templates[index];const planner=t[1]==='플래너';return [{type:'text',content:planner?'이번 주, 나를 위한 작은 약속':t[0],x:43,y:28},{type:'photo',content:photos[t[2]],x:57,y:103,w:310,h:270},{type:'sticker',content:t[4],x:415,y:110},{type:'sticker',content:'✨',x:390,y:285},{type:'text',content:planner?'월 □ 나를 위한 시간 만들기\n화 □ 좋아하는 음악 듣기\n수 □ 산책하며 하늘 보기\n목 □ 소중한 순간 남기기\n금 □ 이번 주의 나 칭찬하기':'오늘은 어떤 하루였나요?\n작은 행복들을 이곳에 남겨보세요.\n\n두 번 눌러 나만의 이야기를 적어요 ♡',x:51,y:418},{type:'sticker',content:'🤍',x:463,y:641}]}
function openEditor(d=null,index=0){current=d?JSON.parse(JSON.stringify(d)):{id:crypto.randomUUID(),title:'오늘의 작은 기록',date:new Date().toLocaleDateString('sv-SE').replaceAll('-','.'),image:templates[index][2],template:index};$('#title-input').value=current.title;$('#paper').replaceChildren();$('#paper').style.backgroundColor=current.background||'#fffdf7';$('#paper-color').value=current.background||'#fffdf7';(current.items||defaultItems(current.template||0)).forEach(addPiece);selected=null;dirty=false;$('#editor').classList.remove('hidden');document.body.style.overflow='hidden';}
function addPiece(data){const piece=el('div','piece '+data.type);piece.dataset.type=data.type;piece.style.left=data.x+'px';piece.style.top=data.y+'px';if(data.type==='photo'){const img=el('img');img.src=data.content;img.alt='다이어리 사진';piece.append(img);piece.style.width=(data.w||220)+'px';piece.style.height=(data.h||190)+'px'}else piece.textContent=data.content;
piece.onpointerdown=e=>{if(piece.isContentEditable)return;$$('.piece').forEach(p=>p.classList.remove('selected'));piece.classList.add('selected');selected=piece;const box=piece.getBoundingClientRect();if(data.type==='photo'&&e.clientX>box.right-22&&e.clientY>box.bottom-22){dirty=true;return}e.preventDefault();piece.setPointerCapture(e.pointerId);const x=e.clientX,y=e.clientY,left=piece.offsetLeft,top=piece.offsetTop;piece.onpointermove=ev=>{piece.style.left=Math.max(0,Math.min(600-piece.offsetWidth,left+ev.clientX-x))+'px';piece.style.top=Math.max(0,Math.min(760-piece.offsetHeight,top+ev.clientY-y))+'px';dirty=true};piece.onpointerup=()=>{piece.onpointermove=null;piece.onpointerup=null}};
if(data.type==='text'){piece.ondblclick=()=>{piece.contentEditable='true';piece.focus()};piece.onblur=()=>{piece.contentEditable='false';dirty=true};piece.oninput=()=>dirty=true;piece.onpaste=e=>{e.preventDefault();const text=e.clipboardData.getData('text/plain');const sel=window.getSelection();if(sel.rangeCount){const range=sel.getRangeAt(0);range.deleteContents();range.insertNode(document.createTextNode(text));sel.collapseToEnd()}}}$('#paper').append(piece);dirty=true;}
function capture(){return {...current,title:$('#title-input').value.trim()||'이름 없는 하루',background:$('#paper-color').value,items:$$('#paper .piece').map(p=>({type:p.dataset.type,content:p.dataset.type==='photo'?p.querySelector('img').src:p.innerText,x:p.offsetLeft,y:p.offsetTop,w:p.offsetWidth,h:p.offsetHeight}))}}
function save(){const d=capture();const next=diaries.some(x=>x.id===d.id)?diaries.map(x=>x.id===d.id?d:x):[d,...diaries];try{localStorage.setItem('diaru-diaries-v1',JSON.stringify(next));diaries=next;current=d;dirty=false;renderDiaries();toast('오늘의 이야기가 저장됐어요 ♡');return true}catch{toast('저장 공간이 부족해요. 사진을 줄이거나 공유 파일로 보관해주세요.');return false}}
$('#save').onclick=save;$('#title-input').oninput=()=>dirty=true;$('#paper-color').oninput=e=>{$('#paper').style.backgroundColor=e.target.value;dirty=true};$('#close-editor').onclick=()=>{if(dirty&&!confirm('저장하지 않은 변경사항이 있어요. 닫을까요?'))return;$('#editor').classList.add('hidden');document.body.style.overflow=''};$$('.new').forEach(b=>b.onclick=()=>openEditor());$('#today').onclick=()=>openEditor();$('#add-text').onclick=()=>addPiece({type:'text',content:'여기에 이야기를 적어보세요',x:70,y:330});$('#add-photo').onclick=()=>$('#photo-input').click();$('#photo-input').onchange=e=>{const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')){toast('이미지 파일을 선택해주세요.');return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');const scale=Math.min(1,1200/img.width,1200/img.height);canvas.width=img.width*scale;canvas.height=img.height*scale;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);addPiece({type:'photo',content:canvas.toDataURL('image/jpeg',.82),x:150,y:220,w:240,h:230});toast('사진을 추가했어요. 원하는 곳으로 옮겨보세요.')};img.onerror=()=>toast('이 사진을 읽을 수 없어요. JPG 또는 PNG를 사용해주세요.');img.src=reader.result};reader.readAsDataURL(file);e.target.value=''};$('#delete-item').onclick=()=>{if(selected){selected.remove();selected=null;dirty=true}else toast('삭제할 글, 사진, 스티커를 먼저 선택해주세요.')};
$('#export').onclick=()=>{const clone=$('#paper').cloneNode(true);clone.querySelectorAll('.piece').forEach(p=>{p.classList.remove('selected');p.removeAttribute('contenteditable')});const title=el('title','',capture().title);const html='<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'+title.outerHTML+'<style>body{margin:30px;background:#eaeef2;display:grid;place-items:center}#paper{position:relative;width:600px;height:760px;overflow:hidden;box-shadow:0 4px 20px #0001;background-image:linear-gradient(#8799ae14 1px,transparent 1px),linear-gradient(90deg,#8799ae14 1px,transparent 1px);background-size:22px 22px}.piece{position:absolute;white-space:pre-wrap}.text{font-family:cursive;font-size:28px;line-height:1.55;padding:4px;max-width:540px}.sticker{font-size:51px}.photo{box-sizing:border-box;padding:8px 8px 26px;background:white;box-shadow:0 3px 8px #0002}.photo img{width:100%;height:100%;object-fit:cover}</style>'+clone.outerHTML+'</html>';const blob=new Blob([html],{type:'text/html;charset=utf-8'});const url=URL.createObjectURL(blob);const a=el('a');a.href=url;a.download=capture().title.replace(/[<>:"/\\|?*]/g,'')+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('공유 파일을 다운로드했어요. 친구에게 보내보세요!')};$('#help').onclick=()=>toast('템플릿을 고르고 사진과 스티커를 붙여보세요. 기록은 이 브라우저에 저장돼요.');window.addEventListener('beforeunload',e=>{if(dirty&&!$('#editor').classList.contains('hidden')){e.preventDefault();e.returnValue=''}});
renderDiaries();renderTemplates('#home-templates',templates.slice(0,4));renderTemplates('#all-templates',templates);renderStickers();

